//! Hand-written `extern "C"` declarations mirroring Pollux Core's
//! published ABI header (`pollux.h`, generated by `cbindgen` from
//! `pollux-ffi` — see `ARTIFACT_LAYOUT.md`). This module is the *only*
//! place in this crate that talks to Core directly; everything above it
//! in `lib.rs` is a safe wrapper.
//!
//! No decision logic, Capability/Resource semantics, or Contract
//! evaluation exist here or anywhere else in this crate — every symbol
//! below is a thin passthrough to Pollux Core.

use std::os::raw::c_char;

/// Mirrors `enum PolluxStatus` in `pollux.h`. Field-for-field, value-for-
/// value identical — this is the ABI contract, not a local invention.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PolluxStatus {
    Ok = 0,
    NullArgument = 1,
    InvalidUtf8 = 2,
    ManifestError = 3,
    OperationError = 4,
    InternalError = 5,
}

/// Mirrors the opaque `struct PolluxEngineHandle` in `pollux.h`. This
/// crate never defines or reads its layout — it only ever holds a raw
/// pointer to one, exactly as the ABI contract requires.
#[repr(C)]
pub struct PolluxEngineHandle {
    _private: [u8; 0],
}

#[cfg_attr(windows, link(name = "pollux_ffi", kind = "raw-dylib"))]
extern "C" {
    pub fn pollux_abi_version() -> *const c_char;
    pub fn pollux_core_version() -> *const c_char;

    pub fn pollux_engine_create(
        manifest_ptr: *const u8,
        manifest_len: usize,
        out_engine: *mut *mut PolluxEngineHandle,
    ) -> PolluxStatus;

    pub fn pollux_engine_evaluate(
        engine: *mut PolluxEngineHandle,
        operation_json_ptr: *const u8,
        operation_json_len: usize,
        out_result: *mut *mut c_char,
    ) -> PolluxStatus;

    pub fn pollux_string_free(ptr: *mut c_char);

    pub fn pollux_engine_destroy(engine: *mut PolluxEngineHandle);
}
